public class Solution {
    enum Fase { SLOW_START, CONGESTION_AVOIDANCE, FAST_RECOVERY }

    static final class JanelaDeCongestionamento {
        private int cwnd;
        private int ssthresh;
        private int acksNaFase = 0;      // ACKs acumulados em congestion avoidance (a cada `cwnd` ACKs, cwnd sobe 1)
        private int duplicados = 0;
        private boolean recuperando = false;
        private long retransmissoesRapidas = 0;
        private long timeouts = 0;

        JanelaDeCongestionamento(int cwndInicial, int ssthreshInicial) {
            if (cwndInicial < 1) throw new IllegalArgumentException("cwnd inicial precisa ser >= 1");
            if (ssthreshInicial < 2) throw new IllegalArgumentException("ssthresh inicial precisa ser >= 2");
            this.cwnd = cwndInicial;
            this.ssthresh = ssthreshInicial;
        }

        int cwnd() { return cwnd; }
        int ssthresh() { return ssthresh; }
        long retransmissoesRapidas() { return retransmissoesRapidas; }
        long timeouts() { return timeouts; }

        Fase fase() {
            if (recuperando) return Fase.FAST_RECOVERY;
            return cwnd < ssthresh ? Fase.SLOW_START : Fase.CONGESTION_AVOIDANCE;
        }

        /** Um ACK novo, que confirma 1 MSS de dados. */
        void ack() {
            duplicados = 0;
            if (recuperando) {                       // o ACK novo encerra a recuperação: desinfla a janela
                recuperando = false;
                cwnd = ssthresh;
                acksNaFase = 0;
                return;
            }
            if (cwnd < ssthresh) {
                cwnd++;                              // slow start: +1 MSS por ACK (dobra por RTT)
            } else if (++acksNaFase >= cwnd) {       // congestion avoidance: +1 MSS a cada cwnd ACKs (1 por RTT)
                cwnd++;
                acksNaFase = 0;
            }
        }

        /** Os ACKs de uma rodada inteira: tantos ACKs novos quanto a cwnd no início da rodada. */
        void rodada() {
            int n = cwnd;
            for (int i = 0; i < n; i++) ack();
        }

        void ackDuplicado() {
            if (recuperando) {
                cwnd++;                              // cada duplicado indica que um segmento saiu da rede: infla a janela
                return;
            }
            if (++duplicados == 3) {
                ssthresh = Math.max(cwnd / 2, 2);
                cwnd = ssthresh + 3;
                recuperando = true;
                retransmissoesRapidas++;
            }
        }

        void timeout() {
            ssthresh = Math.max(cwnd / 2, 2);
            cwnd = 1;
            acksNaFase = 0;
            duplicados = 0;
            recuperando = false;
            timeouts++;
        }

        /** Quantos MSS podem ser enviados agora: o menor entre a janela do receptor e a de congestionamento. */
        int podeEnviar(int rwnd) {
            if (rwnd < 0) throw new IllegalArgumentException("rwnd negativa");
            return Math.min(rwnd, cwnd);
        }
    }
}

