import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.ArrayList;
import java.util.List;

class SolutionTest {
    static Solution.JanelaDeCongestionamento j(int cwnd, int ssthresh) {
        return new Solution.JanelaDeCongestionamento(cwnd, ssthresh);
    }

    static void acks(Solution.JanelaDeCongestionamento w, int n) { for (int i = 0; i < n; i++) w.ack(); }
    static void duplicados(Solution.JanelaDeCongestionamento w, int n) { for (int i = 0; i < n; i++) w.ackDuplicado(); }

    // ---------- estado inicial ----------

    @Test void estadoInicial() {
        Solution.JanelaDeCongestionamento w = j(10, 64);
        assertEquals(10, w.cwnd());
        assertEquals(64, w.ssthresh());
        assertEquals(Solution.Fase.SLOW_START, w.fase());
        assertEquals(0, w.retransmissoesRapidas());
        assertEquals(0, w.timeouts());
    }

    @Test void argumentosInvalidos() {
        assertThrows(IllegalArgumentException.class, () -> j(0, 10));
        assertThrows(IllegalArgumentException.class, () -> j(-1, 10));
        assertThrows(IllegalArgumentException.class, () -> j(10, 1));
        assertThrows(IllegalArgumentException.class, () -> j(10, 0));
        assertThrows(IllegalArgumentException.class, () -> j(10, 10).podeEnviar(-1));
    }

    @Test void comecarJaEmCongestionAvoidance() {
        assertEquals(Solution.Fase.CONGESTION_AVOIDANCE, j(10, 10).fase());
        assertEquals(Solution.Fase.CONGESTION_AVOIDANCE, j(20, 10).fase());
    }

    // ---------- slow start ----------

    @Test void slowStartSomaUmPorAck() {
        Solution.JanelaDeCongestionamento w = j(1, 64);
        w.ack();
        assertEquals(2, w.cwnd());
        w.ack();
        assertEquals(3, w.cwnd());
    }

    @Test void slowStartDobraACadaRodada() {
        Solution.JanelaDeCongestionamento w = j(10, 40);
        w.rodada();
        assertEquals(20, w.cwnd());
        w.rodada();
        assertEquals(40, w.cwnd());
        assertEquals(Solution.Fase.CONGESTION_AVOIDANCE, w.fase(), "chegou ao ssthresh");
    }

    @Test void slowStartParaExatamenteNoSsthresh() {
        Solution.JanelaDeCongestionamento w = j(8, 13);
        w.rodada();
        assertEquals(13, w.cwnd(), "dobrar daria 16, mas o slow start termina em 13");
        assertEquals(Solution.Fase.CONGESTION_AVOIDANCE, w.fase());
        w.rodada();
        assertEquals(14, w.cwnd());
        w.rodada();
        assertEquals(15, w.cwnd());
    }

    // ---------- congestion avoidance ----------

    @Test void congestionAvoidanceSomaUmACadaCwndAcks() {
        Solution.JanelaDeCongestionamento w = j(40, 40);
        acks(w, 39);
        assertEquals(40, w.cwnd(), "faltou 1 ACK");
        w.ack();
        assertEquals(41, w.cwnd());
        acks(w, 40);
        assertEquals(41, w.cwnd(), "agora são necessários 41 ACKs");
        w.ack();
        assertEquals(42, w.cwnd());
    }

    @Test void congestionAvoidanceCrescimentoLinearPorRodada() {
        Solution.JanelaDeCongestionamento w = j(40, 40);
        for (int esperado = 41; esperado <= 44; esperado++) {
            w.rodada();
            assertEquals(esperado, w.cwnd());
        }
    }

    // ---------- 3 ACKs duplicados (Reno) ----------

    @Test void doisDuplicadosNaoFazemNada() {
        Solution.JanelaDeCongestionamento w = j(44, 40);
        duplicados(w, 2);
        assertEquals(44, w.cwnd());
        assertEquals(40, w.ssthresh());
        assertEquals(0, w.retransmissoesRapidas());
    }

    @Test void terceiroDuplicadoDisparaFastRetransmitEFastRecovery() {
        Solution.JanelaDeCongestionamento w = j(44, 40);
        duplicados(w, 3);
        assertEquals(22, w.ssthresh(), "metade de 44");
        assertEquals(25, w.cwnd(), "ssthresh + 3 segmentos que já saíram da rede");
        assertEquals(Solution.Fase.FAST_RECOVERY, w.fase());
        assertEquals(1, w.retransmissoesRapidas());
    }

    @Test void duplicadosExtrasInflamAJanelaNaRecuperacao() {
        Solution.JanelaDeCongestionamento w = j(44, 40);
        duplicados(w, 3);
        duplicados(w, 2);
        assertEquals(27, w.cwnd());
        assertEquals(22, w.ssthresh());
        assertEquals(1, w.retransmissoesRapidas(), "continua sendo uma única perda");
    }

    @Test void ackNovoEncerraARecuperacaoEDesinflaAJanela() {
        Solution.JanelaDeCongestionamento w = j(44, 40);
        duplicados(w, 4);
        w.ack();
        assertEquals(22, w.cwnd());
        assertEquals(22, w.ssthresh());
        assertEquals(Solution.Fase.CONGESTION_AVOIDANCE, w.fase());
        w.rodada();
        assertEquals(23, w.cwnd(), "depois da recuperação, cresce linearmente");
    }

    @Test void ackNovoZeraAContagemDeDuplicados() {
        Solution.JanelaDeCongestionamento w = j(30, 20);
        duplicados(w, 2);
        w.ack();
        duplicados(w, 2);
        assertEquals(0, w.retransmissoesRapidas(), "2 + ACK novo + 2 não são 3 seguidos");
        w.ackDuplicado();
        assertEquals(1, w.retransmissoesRapidas());
    }

    @Test void ssthreshNuncaFicaAbaixoDeDois() {
        Solution.JanelaDeCongestionamento w = j(3, 10);
        duplicados(w, 3);
        assertEquals(2, w.ssthresh(), "3 / 2 = 1, mas o mínimo é 2");
        assertEquals(5, w.cwnd());
    }

    @Test void cwndImparArredondaParaBaixo() {
        Solution.JanelaDeCongestionamento w = j(45, 100);
        duplicados(w, 3);
        assertEquals(22, w.ssthresh());
    }

    // ---------- timeout ----------

    @Test void timeoutVoltaParaUmMssEReduzOSsthreshAMetade() {
        Solution.JanelaDeCongestionamento w = j(26, 22);
        w.timeout();
        assertEquals(1, w.cwnd());
        assertEquals(13, w.ssthresh());
        assertEquals(Solution.Fase.SLOW_START, w.fase());
        assertEquals(1, w.timeouts());
    }

    @Test void timeoutComCwndPequenaMantemSsthreshMinimo() {
        Solution.JanelaDeCongestionamento w = j(2, 10);
        w.timeout();
        assertEquals(2, w.ssthresh());
        assertEquals(1, w.cwnd());
    }

    @Test void depoisDoTimeoutOSlowStartRecomecaAteOSsthresh() {
        Solution.JanelaDeCongestionamento w = j(26, 22);
        w.timeout();
        List<Integer> vistas = new ArrayList<>();
        for (int i = 0; i < 6; i++) {
            vistas.add(w.cwnd());
            w.rodada();
        }
        assertEquals(List.of(1, 2, 4, 8, 13, 14), vistas);
    }

    @Test void timeoutDuranteAFastRecoveryAbandonaARecuperacao() {
        Solution.JanelaDeCongestionamento w = j(44, 40);
        duplicados(w, 3);
        w.timeout();
        assertEquals(1, w.cwnd());
        assertEquals(Solution.Fase.SLOW_START, w.fase());
        assertEquals(12, w.ssthresh(), "metade da cwnd inflada (25) arredondada para baixo");
        w.ack();
        assertEquals(2, w.cwnd(), "um ACK novo agora é slow start, e não desinflação");
    }

    @Test void timeoutZeraAContagemDeDuplicados() {
        Solution.JanelaDeCongestionamento w = j(30, 20);
        duplicados(w, 2);
        w.timeout();
        w.ackDuplicado();
        assertEquals(0, w.retransmissoesRapidas());
    }

    // ---------- janela efetiva ----------

    @Test void envioEfetivoEOMenorEntreRwndECwnd() {
        Solution.JanelaDeCongestionamento w = j(10, 64);
        assertEquals(10, w.podeEnviar(64));
        assertEquals(4, w.podeEnviar(4));
        assertEquals(0, w.podeEnviar(0), "janela zero do receptor");
    }

    // ---------- o exemplo completo da aula ----------

    @Test void sequenciaDaCenaDeCongestionamento() {
        Solution.JanelaDeCongestionamento w = j(10, 40);
        List<Integer> cwndPorRtt = new ArrayList<>();
        for (int rtt = 0; rtt <= 17; rtt++) {
            cwndPorRtt.add(w.cwnd());
            if (rtt == 6) {            // perda: 3 ACKs duplicados e depois o ACK que a recupera
                duplicados(w, 3);
                w.ack();
            } else if (rtt == 11) {    // timeout
                w.timeout();
            } else {
                w.rodada();
            }
        }
        assertEquals(List.of(10, 20, 40, 41, 42, 43, 44, 22, 23, 24, 25, 26, 1, 2, 4, 8, 13, 14), cwndPorRtt);
        assertEquals(1, w.retransmissoesRapidas());
        assertEquals(1, w.timeouts());
        assertEquals(13, w.ssthresh());
    }

    @Test void ssthreshInfinitoNaPratica() {
        Solution.JanelaDeCongestionamento w = j(10, Integer.MAX_VALUE);
        for (int i = 0; i < 8; i++) w.rodada();
        assertEquals(2560, w.cwnd(), "10 × 2^8");
        assertEquals(Solution.Fase.SLOW_START, w.fase());
    }
}
